parameters.jsonSchemaExample:
{
  "type": "object",
  "properties": {
    "summary": {
      "type": "string",
      "description": "Краткое резюме разговора (5–15 предложений): что обсудили, на чем сделали акцент, каков общий настрой клиента, какой результат по итогу встречи. Укажи основные моменты, выводы и решения, к которым пришли."
    },
    "client_talks_most": {
      "type": "string",
      "description": "Напиши кто говорил больше (да/нет + краткое пояснение). Например: 'Да, клиент делился своими вопросами и опытом, задавал уточняющие вопросы', или 'Нет, менеджер вел беседу, клиент отвечал коротко'."
    },
    "client_name": {
      "type": "string",
      "description": "Напиши имя клиента (по возможности ФИО). Например: 'Иванов Иван'."
    },
    "style_adaptation": {
      "type": "string",
      "description": "Была ли адаптация стиля менеджера под клиента (да/нет + пояснение). Оцени, насколько менеджер подстроился под стиль общения клиента, использовал ли его лексику, темп, энергетику, формат шуток или профессиональный сленг. 8-15 предложений. С цитатами из транскрибации"
    },
    "target_client": {
      "type": "string",
      "description": "Оцени целевой ли клиент для клуба (да/нет + пояснение). Например: 'Да, владелец агентства, есть запрос на рост и развитие', или 'Нет, частный специалист, не планирует масштабироваться'."
    },
    "client_needs": {
      "type": "string",
      "description": "Оцени основные потребности и мотивация клиента. Зачем клиенту вступать в клуб, каких целей он хочет достичь, что для него важно. 8-15 предложений. С цитатами из транскрибации"
    },
    "manager_responsible": {
      "type": "string",
      "description": "Скажи ФИО менеджера, который проводил встречу или несет ответственность за клиента."
    },
    "contact_establishment": {
      "type": "object",
      "properties": {
        "value": {
          "type": "number",
          "description": "Дай оценку установления контакта (0–100). Насколько успешно менеджер установил контакт: был ли смолток, удалось ли расположить клиента, плавность перехода к делу."
        },
        "explanation": {
          "type": "string",
          "description": "дай пояснение по установлению контакта. Как прошел первый этап встречи, были ли барьеры, удалось ли быстро перейти к сути, насколько доверительно сложилось общение. 8-15 предложений. С цитатами из транскрибации"
        }
      },
      "required": ["value", "explanation"]
    },
    "qualification": {
      "type": "object",
      "properties": {
        "value": {
          "type": "number",
          "description": "Дай оценку квалификации клиента (0–100). Насколько глубоко выяснили, кто клиент, его контекст, источник знакомства с клубом, мотивацию на данном этапе."
        },
        "explanation": {
          "type": "string",
          "description": "Дай пояснения по квалификации. Какие вопросы были заданы, насколько полно менеджер раскрыл контекст и мотивацию клиента: спросил ли о бизнесе, текущих задачах, почему ищет решение сейчас, как узнал о клубе. 8-15 предложений. С цитатами из транскрибации"
        }
      },
      "required": ["value", "explanation"]
    },
    "needs_identification": {
      "type": "object",
      "properties": {
        "value": {
          "type": "number",
          "description": "Дай оценку выявления потребностей (0–100). Насколько четко и глубоко выявлены реальные потребности и цели клиента, получены как минимум 4 задачи или проблемы, использованы уточняющие вопросы."
        },
        "explanation": {
          "type": "string",
          "description": "Дай пояснения по выявлению потребностей. Какие задачи, боли и ожидания клиента были зафиксированы, насколько глубоко менеджер понял истинные мотивы и цели. 8-15 предложений. С цитатами из транскрибации"
        }
      },
      "required": ["value", "explanation"]
    },
    "product_presentation": {
      "type": "object",
      "properties": {
        "value": {
          "type": "number",
          "description": "Дай оценку презентации продукта (0–100). Насколько презентация была адаптирована под задачи клиента, использованы ли цитаты, кейсы, примеры, метафоры, даны ли конкретные форматы клуба и ближайшие мероприятия."
        },
        "explanation": {
          "type": "string",
          "description": "Дай пояснения по презентации. Какие выгоды и решения были показаны, насколько персонализированно менеджер рассказывал о клубе, делал ли акцент на боли и мотивации клиента. 8-15 предложений. С цитатами из транскрибации"
        }
      },
      "required": ["value", "explanation"]
    },
    "objection_handling": {
      "type": "object",
      "properties": {
        "value": {
          "type": "number",
          "description": "Дай оценку работы с возражениями (0–100). Как менеджер работал с возражениями, насколько эффективно снял опасения клиента, отработал хотя бы два типа возражений."
        },
        "explanation": {
          "type": "string",
          "description": "Дай пояснения по работе с возражениями. Какие вопросы или возражения звучали, как менеджер их закрыл, что сработало лучше всего. 8-15 предложений. С цитатами из транскрибации"
        }
      },
      "required": ["value", "explanation"]
    },
    "hidden_objections": {
      "type": "string",
      "description": "Скажи скрытые возражения, которые не были отработаны. Запиши неочевидные опасения или вопросы, которые могли остаться у клиента. 8-15 предложений. С цитатами из транскрибации"
    },
    "closing": {
      "type": "object",
      "properties": {
        "value": {
          "type": "number",
          "description": "Дай оценку закрытия сделки (0–100). Была ли попытка закрытия (например, предложен ван-тайм оффер), насколько корректно и уверенно менеджер сделал предложение."
        },
        "explanation": {
          "type": "string",
          "description": "Дай пояснения по закрытию сделки. Что именно предложил менеджер, как отреагировал клиент, было ли согласие или нет, что повлияло на решение. 8-15 предложений. С цитатами из транскрибации"
        }
      },
      "required": ["value", "explanation"]
    },
    "sale_probability": {
      "type": "object",
      "properties": {
        "value": {
          "type": "number",
          "description": "Скажи вероятность продажи (0–100). Субъективная оценка, насколько клиент готов купить после встречи."
        },
        "explanation": {
          "type": "string",
          "description": "Дай краткое объяснение вероятности продажи. Что говорит за и против, какие сигналы дал клиент (например, выражал интерес, задавал вопросы, назвал сроки или условия). 2-5 предложений."
        }
      },
      "required": ["value", "explanation"]
    },
    "next_step": {
      "type": "string",
      "description": "Скажи следующий шаг после встречи. Что согласовали, какие действия стоит сделать менеджеру дальше, чтобы не потерять динамику. Например: 'Отправить презентацию', 'Назначить повторную встречу', 'Дать дополнительную информацию'."
    }
  },
  "required": [
    "summary",
    "client_talks_most",
    "client_name",
    "style_adaptation",
    "target_client",
    "client_needs",
    "manager_responsible",
    "contact_establishment",
    "qualification",
    "needs_identification",
    "product_presentation",
    "objection_handling",
    "hidden_objections",
    "closing",
    "sale_probability",
    "next_step"
  ]
}
